'use strict';
// Requirement: PRD-075 (docs/PRD.md).
// tests/tools/gen-shapes.test.js — schema/item-shapes.ttl holds the SHACL shapes of
// AGSC-05-24, generated by tools/gen-shapes from `schema/item.schema.json`, the
// relation table of AGSC-03-01 (the Expected target kinds and Self-link columns,
// AGSC-03-25) and the SKOS integrity rules AGSC-05-17 to AGSC-05-21. The suite fails
// when the committed file is not what the tool generates, reads the file back with the
// pinned `n3`, and checks it against the sources it is derived from. The development
// lane that RUNS the shapes (pySHACL) is `gen-shapes-lane.test.js`.
//
// Deterministic: reads the repository and temporary copies; no clock, no network.

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { describe, it } = require('node:test');
const fc = require('fast-check');
const N3 = require('n3');

const relations = require('../../src/knowledge/relations.js');
const { REPO, capture, codes, envelope, tmpdir, tool } = require('./helpers');

const generator = tool('gen-shapes');
const SHAPES_FILE = path.join(REPO, 'schema', 'item-shapes.ttl');
const NEGATIVES = path.join(REPO, 'tests', 'shapes', 'negative');
const SH = 'http://www.w3.org/ns/shacl#';
const RDF_TYPE = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type';
const ASC = 'https://w3id.org/agentic-system-core/ns#';
const ASCS = 'https://w3id.org/agentic-system-core/shapes#';
const CURIES = { asc: ASC, schema: 'https://schema.org/', dcterms: 'http://purl.org/dc/terms/', prov: 'http://www.w3.org/ns/prov#', skos: 'http://www.w3.org/2004/02/skos/core#' };

/** The committed file as an n3 store. */
function readShapes() {
  return new N3.Store(new N3.Parser().parse(fs.readFileSync(SHAPES_FILE, 'utf8')));
}

const local = (iri) => iri.slice(ASCS.length);
const expand = (curie) => { const [p, rest] = curie.split(':'); return `${CURIES[p]}${rest}`; };
const objects = (store, subject, predicate) => store.getObjects(N3.DataFactory.namedNode(subject), N3.DataFactory.namedNode(predicate), null);

/** Every shape that carries a constraint of its own and so can be the source shape of a result. */
const CONSTRAINTS = ['datatype', 'in', 'minCount', 'maxCount', 'class', 'nodeKind', 'uniqueLang', 'node', 'or', 'not', 'sparql'].map((n) => `${SH}${n}`);
function reportingShapes(store) {
  const shapes = [...store.getSubjects(RDF_TYPE, null, null)]
    .filter((s) => store.getObjects(s, RDF_TYPE, null).some((o) => [`${SH}NodeShape`, `${SH}PropertyShape`].includes(o.value)));
  return shapes.filter((s) => CONSTRAINTS.some((c) => store.getObjects(s, c, null).length > 0)).map((s) => s.value);
}

const members = (store, head) => {
  const out = [];
  let node = head;
  while (node && node.value !== 'http://www.w3.org/1999/02/22-rdf-syntax-ns#nil') {
    out.push(store.getObjects(node, 'http://www.w3.org/1999/02/22-rdf-syntax-ns#first', null)[0]);
    [node] = store.getObjects(node, 'http://www.w3.org/1999/02/22-rdf-syntax-ns#rest', null);
  }
  return out;
};

describe('tools/gen-shapes', () => {
  it('the committed schema/item-shapes.ttl is exactly what the tool generates (--check)', () => {
    const r = capture('gen-shapes', ['--check']);
    assert.equal(r.code, 0, r.err);
    assert.match(r.out, /^schema\/item-shapes\.ttl: current \(\d+ shapes\)\n$/u);
  });

  it('the file is Turtle whose node shapes and property shapes are all named by an IRI of the shapes namespace', () => {
    const store = readShapes();
    const typed = [...store.getQuads(null, RDF_TYPE, null, null)]
      .filter((q) => [`${SH}NodeShape`, `${SH}PropertyShape`].includes(q.object.value));
    assert.ok(typed.length >= 40, `${typed.length} shapes`);
    for (const q of typed) {
      assert.equal(q.subject.termType, 'NamedNode', 'a shape is a blank node');
      assert.ok(q.subject.value.startsWith(ASCS), q.subject.value);
    }
  });

  it('every link key whose Expected target kinds is not "any" has a target shape, and a key that reads any has none', () => {
    const store = readShapes();
    const named = new Set(reportingShapes(store).map(local));
    for (const row of relations.RELATIONS) {
      const restricted = !row.targets.any || row.targets.lessonTarget;
      assert.equal(named.has(`Link-${row.key}-target`), Boolean(restricted), row.key);
    }
  });

  it('a link target shape is a warning (AGSC-E315), on the property of the key', () => {
    const store = readShapes();
    for (const row of relations.RELATIONS.filter((r) => !r.targets.any || r.targets.lessonTarget)) {
      const shape = `${ASCS}Link-${row.key}-target`;
      assert.deepEqual(objects(store, shape, `${SH}severity`).map((o) => o.value), [`${SH}Warning`], row.key);
      assert.deepEqual(objects(store, shape, `${SH}path`).map((o) => o.value), [expand(row.property)], row.key);
    }
  });

  it('the kinds a target shape lists are the kinds of the table', () => {
    const store = readShapes();
    const text = fs.readFileSync(SHAPES_FILE, 'utf8');
    const block = (key) => text.slice(text.indexOf(`ascs:Link-${key}-target\n`)).split('\n\n')[0];
    assert.match(block('implements'), /"spec" "pattern" "architecture"/u);
    assert.match(block('verifies'), /"spec" "task"/u);
    assert.match(block('blocked-by'), /"task"/u);
    assert.match(block('decided-by'), /"decision"/u);
    assert.match(block('derived-from'), /asc:Lesson/u);
    assert.match(block('derived-from'), /asc:Episode/u);
    assert.ok(store.size > 0);
  });

  it('the self-link warning names the properties of the keys the table marks "warning", and the cycles those it marks "cycle"', () => {
    const text = fs.readFileSync(SHAPES_FILE, 'utf8');
    const self = text.slice(text.indexOf('ascs:SelfLinkShape\n')).split('\n\n')[0];
    for (const row of relations.RELATIONS) {
      assert.equal(self.includes(`${row.property},`) || self.includes(`${row.property})`), row.selfLink === 'warning', row.key);
    }
    const cycles = relations.RELATIONS.filter((r) => r.selfLink === 'cycle').map((r) => r.key);
    assert.deepEqual(cycles, ['broader', 'narrower', 'requires']);
    assert.ok(text.includes('ascs:NoCycle-requires\n') && text.includes('ascs:NoCycle-broader\n'));
    assert.ok(!text.includes('ascs:NoCycle-narrower\n'), 'broader and narrower are one cycle shape');
  });

  it('a closed list of the item schema is an sh:in, a required key of a branch is a minCount, and every property is single-valued', () => {
    const schema = JSON.parse(fs.readFileSync(path.join(REPO, 'schema', 'item.schema.json'), 'utf8'));
    const store = readShapes();
    const inOf = (name) => members(store, objects(store, `${ASCS}${name}`, `${SH}in`)[0]).map((t) => t.value);
    assert.deepEqual(inOf('Item-status'), schema.properties.status.enum);
    assert.deepEqual(inOf('Item-origin'), schema.$defs.prov.properties.origin.enum);
    assert.deepEqual(inOf('Source-grade'), schema.$defs.source.properties.grade.enum);
    const branch = (title) => schema.oneOf.find((b) => b.title === title);
    assert.deepEqual(inOf('Concept-kind'), branch('concept').properties.kind.enum);
    assert.deepEqual(inOf('Gate-level'), branch('gate').properties.level.enum);
    assert.deepEqual(inOf('Lesson-severity'), branch('lesson').properties.severity.enum);
    assert.deepEqual(inOf('Episode-outcome'), branch('episode').properties.outcome.enum);
    for (const name of ['Concept-kind', 'Gate-level', 'Lesson-severity', 'Episode-outcome']) {
      assert.deepEqual(objects(store, `${ASCS}${name}`, `${SH}minCount`).map((o) => o.value), ['1'], name);
    }
    assert.deepEqual(objects(store, `${ASCS}Item-status`, `${SH}minCount`), [], 'status is optional');
    assert.deepEqual(objects(store, `${ASCS}Item-status`, `${SH}maxCount`).map((o) => o.value), ['1']);
  });

  it('every property of the AGSC-05-26 table is the path of a shape', () => {
    const spec = fs.readFileSync(path.join(REPO, 'spec', '05-graph.md'), 'utf8');
    const lines = spec.slice(spec.indexOf('| Frontmatter key |')).split('\n');
    const rows = lines.slice(2, lines.findIndex((line) => !line.startsWith('|')));
    const wanted = new Set(rows.map((line) => expand(line.split('|')[3].trim().replace(/`/gu, ''))));
    const store = readShapes();
    const paths = new Set(store.getObjects(null, `${SH}path`, null).map((o) => o.value));
    assert.ok(wanted.size >= 20, 'the table was not found');
    for (const property of wanted) assert.ok(paths.has(property), property);
  });

  it('the SKOS integrity rules AGSC-05-17 to AGSC-05-21 each have a shape', () => {
    const named = new Set(reportingShapes(readShapes()).map(local));
    for (const name of ['Concept-inScheme', 'Concept-prefLabel', 'Concept-altLabel', 'Concept-noMember', 'Collection-noBroader',
      'Collection-noNarrower', 'Collection-noRelated', 'Relation-broader', 'Relation-narrower', 'Relation-related',
      'Definition-required', 'NoCycle-broader', 'NoCycle-requires', 'UndefinedResourceShape', 'OrphanShape']) {
      assert.ok(named.has(name), name);
    }
  });

  it('every shape that can report has a negative fixture, and every fixture names a shape of the file', () => {
    const shapes = reportingShapes(readShapes()).map(local).sort();
    const files = fs.readdirSync(NEGATIVES).filter((f) => f.endsWith('.ttl')).map((f) => f.slice(0, -4)).sort();
    assert.deepEqual(files, shapes);
    for (const name of files) {
      const text = fs.readFileSync(path.join(NEGATIVES, `${name}.ttl`), 'utf8');
      assert.ok(text.startsWith(`# ${name}: `), `${name}.ttl opens with a comment that says what it breaks`);
      assert.doesNotThrow(() => new N3.Parser().parse(text), name);
    }
  });

  it('the shapes name the rules they come from, and no shape claims more than SHACL 1.0 and SPARQL 1.1', () => {
    const text = fs.readFileSync(SHAPES_FILE, 'utf8');
    for (const rule of ['AGSC-03-25', 'AGSC-03-23', 'AGSC-05-17', 'AGSC-05-19', 'AGSC-05-20', 'AGSC-05-21', 'AGSC-05-24']) {
      assert.ok(text.includes(rule), rule);
    }
    assert.ok(!/\bsh:(?:rule|TripleRule|SPARQLRule|expression|xone|qualifiedValueShape)\b/u.test(text), 'a term outside SHACL 1.0 Core and SHACL-SPARQL');
    assert.ok(!/\bVALUES\b|\bMINUS\b|\bSERVICE\b/u.test(text), 'SHACL-SPARQL forbids these clauses (SHACL 1.0 section 5.2.1)');
  });

  it('--json is the AGSC-09-11 envelope of the tool, and a current file has no finding', () => {
    const r = envelope('gen-shapes', ['--check']);
    assert.equal(r.json.verb, 'gen-shapes');
    assert.equal(r.json.schema, 'agsc.diagnostics.v1');
    assert.equal(r.json.status, 'pass');
    assert.deepEqual(r.json.findings, []);
  });

  it('--help prints the usage; an unknown flag or a second root is usage, exit 2', () => {
    const help = capture('gen-shapes', ['--help']);
    assert.equal(help.code, 0);
    assert.match(help.out, /^gen-shapes \[--check\]/u);
    assert.equal(capture('gen-shapes', ['--nope']).code, 2);
    assert.equal(capture('gen-shapes', ['a', 'b']).code, 2);
  });

  it('a stale file fails --check with AGSC-E602, a write makes it current, and the write is idempotent', () => {
    const dir = tmpdir();
    for (const rel of ['schema/item.schema.json', 'spec/03-links.md', 'spec/05-graph.md', 'package.json']) {
      fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
      fs.copyFileSync(path.join(REPO, rel), path.join(dir, rel));
    }
    fs.writeFileSync(path.join(dir, 'schema', 'item-shapes.ttl'), 'edited by hand\n');
    const stale = envelope('gen-shapes', ['--check', dir]);
    assert.equal(stale.code, 1);
    assert.deepEqual(codes(stale.json), ['AGSC-E602']);
    assert.equal(capture('gen-shapes', [dir]).code, 0);
    const written = fs.readFileSync(path.join(dir, 'schema', 'item-shapes.ttl'), 'utf8');
    assert.equal(written, fs.readFileSync(SHAPES_FILE, 'utf8'));
    assert.equal(capture('gen-shapes', [dir]).code, 0);
    assert.equal(fs.readFileSync(path.join(dir, 'schema', 'item-shapes.ttl'), 'utf8'), written);
    assert.equal(capture('gen-shapes', ['--check', dir]).code, 0);
  });

  it('a missing input, a table that is not there, a cell it cannot read and a schema that is not JSON are each AGSC-E901 or AGSC-E201, exit 1', () => {
    const dir = tmpdir();
    assert.deepEqual(codes(envelope('gen-shapes', [dir]).json), ['AGSC-E901']);
    fs.mkdirSync(path.join(dir, 'schema'));
    fs.mkdirSync(path.join(dir, 'spec'));
    fs.writeFileSync(path.join(dir, 'schema', 'item.schema.json'), '{ not json');
    fs.writeFileSync(path.join(dir, 'spec', '03-links.md'), '# no table here\n');
    fs.writeFileSync(path.join(dir, 'spec', '05-graph.md'), '# no table here\n');
    assert.deepEqual(codes(envelope('gen-shapes', [dir]).json), ['AGSC-E201', 'AGSC-E901']);
    const links = fs.readFileSync(path.join(REPO, 'spec', '03-links.md'), 'utf8').replace('| same family |', '| nearly the same |');
    fs.writeFileSync(path.join(dir, 'spec', '03-links.md'), links);
    fs.copyFileSync(path.join(REPO, 'schema', 'item.schema.json'), path.join(dir, 'schema', 'item.schema.json'));
    fs.copyFileSync(path.join(REPO, 'spec', '05-graph.md'), path.join(dir, 'spec', '05-graph.md'));
    const unreadable = envelope('gen-shapes', [dir]);
    assert.deepEqual(codes(unreadable.json), ['AGSC-E901']);
    assert.match(unreadable.json.findings[0].message, /nearly the same/u);
    assert.equal(fs.existsSync(path.join(dir, 'schema', 'item-shapes.ttl')), false);
  });

});

describe('tools/gen-shapes — Turtle text and the claim', () => {
  it('property: a string is written as a Turtle literal that the parser reads back unchanged', () => {
    fc.assert(fc.property(fc.string({ maxLength: 40, unit: 'binary' }), (text) => {
      const [quad] = new N3.Parser().parse(`<urn:s> <urn:p> ${generator.ttlString(text)} .`);
      assert.equal(quad.object.value, text);
    }), { numRuns: 300, seed: 5024 });
  });

  it('property: the long form used for SPARQL text reads back unchanged', () => {
    fc.assert(fc.property(fc.string({ maxLength: 60, unit: 'binary' }), (text) => {
      const [quad] = new N3.Parser().parse(`<urn:s> <urn:p> ${generator.ttlLong(text)} .`);
      assert.equal(quad.object.value, text);
    }), { numRuns: 300, seed: 5025 });
  });

  it('property: generating twice from the same inputs gives the same bytes', () => {
    const inputs = generator.readInputs(REPO);
    assert.deepEqual(inputs.findings, []);
    fc.assert(fc.property(fc.constant(inputs), (given) => {
      assert.equal(generator.generate(given.links, given.graphTable, given.schema).text,
        generator.generate(given.links, given.graphTable, given.schema).text);
    }), { numRuns: 3 });
  });

  it('the shape file is not named "validated by SHACL" anywhere outside the page the lane produced', () => {
    const claim = /validated by SHACL/iu;
    const outside = [];
    const walk = (dir) => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) { if (!['node_modules', '.git', 'spec', 'tests'].includes(entry.name)) walk(full); continue; }
        if (/\.(md|json|js|ttl|feature)$/u.test(entry.name) && claim.test(fs.readFileSync(full, 'utf8'))) outside.push(path.relative(REPO, full));
      }
    };
    walk(REPO);
    assert.deepEqual(outside, ['docs/SHACL-SHAPES.md']);
    assert.ok(fs.readFileSync(path.join(REPO, 'docs', 'SHACL-SHAPES.md'), 'utf8').includes('pySHACL'));
  });
});
